const i=[{level:1,name:"The Greatest Generation",context:"Summarize this for someone from the Greatest Generation (born 1901-1924). Use formal, dignified language with respect and gravitas. Make analogies to: Victory Gardens, radio broadcasts, assembly lines, railroad systems, telegrams, the local general store, wartime rationing, and community barn raisings. Compare complex systems to military operations or factory production lines. Explain digital concepts like 'the internet is like a nationwide telegraph system that sends letters instantly' or 'a computer stores information like a filing cabinet with millions of folders.' Use phrases like 'in plain terms,' 'the practical matter is,' and 'the essential point.' Keep explanations clear, purposeful, and grounded in tangible, real-world parallels they experienced.",description:"Formal dignified tone with Victory Garden and wartime analogies, telegraph-era comparisons, practical factory-line explanations"},{level:2,name:"The Silent Generation",context:"Summarize this for someone from the Silent Generation (born 1925-1945). Use proper, measured language like a well-written memo. Make analogies to: rotary phones, typewriters, the post office mail system, encyclopedias, card catalogs at the library, bank ledgers, filing systems, and television channel dials. Explain modern concepts like 'a search engine works like a librarian who instantly finds the right encyclopedia entry' or 'cloud storage is like having a safe deposit box you can access from any bank branch.' Use expressions like 'to put it simply,' 'the proper way to understand this,' and 'in practical terms.' Focus on reliability, proper procedure, and systematic organization.",description:"Measured memo-style with typewriter and library analogies, encyclopedia references, systematic procedural explanations"},{level:3,name:"Baby Boomer",context:"Summarize this for a Baby Boomer (born 1946-1964). Use clear, thorough explanations like an evening news broadcast. Make analogies to: Polaroid cameras, VCR recordings, telephone directories, Rolodexes, cassette tapes, TV Guide schedules, station wagons, shopping malls, and Woodstock gatherings. Explain modern tech like 'streaming is like having every TV channel and movie rental store available through your remote' or 'social media is like a neighborhood bulletin board where everyone can post and read updates instantly.' Reference familiar brands and experiences. Use phrases like 'here's the bottom line,' 'what this really means,' and 'let me break this down.' Be comprehensive but accessible.",description:"Evening news clarity with VCR and Polaroid analogies, mall-era references, comprehensive bulletin-board explanations"},{level:4,name:"Generation X",context:"Summarize this for Generation X (born 1965-1979). Cut to the chase with no fluff. Make analogies to: mixtapes, dial-up modems, arcade games, MTV music videos, Blockbuster rentals, pagers, answering machines, floppy disks, and mall food courts. Explain concepts like 'an algorithm is like the MTV VJ deciding which videos to play based on what's popular' or 'a firewall is like the bouncer at a club checking IDs.' Reference the transition from analog to digital. Use phrases like 'here's the deal,' 'bottom line,' and 'what you actually need to know.' Be direct, practical, and respect their time. Skip the corporate jargon.",description:"Direct no-fluff style with mixtape and dial-up analogies, MTV-era references, practical Blockbuster-style explanations"},{level:5,name:"Millennial",context:"Summarize this for a Millennial (born 1980-1994). Make it relatable and engaging like a BuzzFeed article. Use analogies to: AIM away messages, burning CDs, iPod playlists, MySpace Top 8, early Facebook, flip phones, Harry Potter houses, Friends episodes, Pokémon evolutions, and Netflix DVD mailers. Explain concepts like 'machine learning is like how Spotify learned your music taste over time' or 'blockchain is like a Google Doc everyone can see but no one can secretly edit.' Use phrases like 'okay so basically,' 'here's the thing,' and 'think of it like.' Reference the analog-to-digital childhood transition. Keep it authentic, slightly nostalgic, and easy to share.",description:"BuzzFeed-style with AIM and iPod analogies, Harry Potter references, Spotify-era relatable explanations"},{level:6,name:"Generation Z",context:"Summarize this for Generation Z (born 1995-2012). Keep it short, visual, and real. Make analogies to: Instagram filters, TikTok algorithms, Discord servers, Minecraft worlds, YouTube recommendations, Spotify Wrapped, iPhone shortcuts, Among Us tasks, and Netflix autoplay. Explain concepts like 'an API is like how apps talk to each other, like when Spotify shares to your Instagram story' or 'encryption is like sending a Snap that only the right person can open.' Use phrases like 'basically,' 'think of it like,' and 'the tldr is.' Break into scannable chunks. Be authentic, skip the corporate speak, and acknowledge when something is actually complicated.",description:"Short scannable format with TikTok and Discord analogies, Instagram-filter references, Spotify Wrapped-style explanations"},{level:7,name:"Generation Alpha",context:"Summarize this for Generation Alpha (born 2013-2025). Make it fun, interactive, and visual. Use analogies to: Roblox experiences, iPad apps, YouTube Kids, voice assistants like Alexa, smart home devices, Minecraft redstone circuits, tablet games, and educational apps like Khan Academy Kids. Explain concepts like 'the internet is like a giant Roblox world where everyone builds and shares things' or 'a password is like your secret code to unlock your favorite game.' Use emojis strategically 🎮✨, break into small chunks, and make it feel like a fun discovery. Use phrases like 'imagine if,' 'it's kind of like,' and 'here's the cool part.' Keep it positive, safe, and age-appropriate.",description:"Fun interactive style with Roblox and iPad analogies 🎮, YouTube Kids references, game-world discovery explanations ✨"}],n=e=>i.find(a=>a.level===e),o=()=>[...i].reverse(),s=i.reduce((e,a)=>(e[a.level]=`${a.name} (${t(a.level)})`,e),{});function t(e){return{1:"1901-1924",2:"1925-1945",3:"1946-1964",4:"1965-1979",5:"1980-1994",6:"1995-2012",7:"2013-2025"}[e]||""}const r={PANEL_OPEN_DELAY:1e3,DEBOUNCE_DELAY:300,CHROME_TARGET_VERSION:"chrome130",STORAGE_KEYS:{CURRENT_LEVEL:"currentLevel",SELECTED_LEVEL:"selectedLevel"},MESSAGE_TYPES:{STREAM_RESPONSE:"STREAM_RESPONSE",ERROR:"ERROR",AI_INITIATE:"AI_INITIATE",STREAM_COMPLETE:"STREAM_COMPLETE",TEXT_SELECTED:"TEXT_SELECTED",RERUN_COMPLETE:"RERUN_COMPLETE",SET_LEVEL:"SET_LEVEL",RERUN_SUMMARIZATION:"RERUN_SUMMARIZATION",CHUNK_PROGRESS:"CHUNK_PROGRESS",CHUNKING_STARTED:"CHUNKING_STARTED",FINAL_SUMMARY_STARTED:"FINAL_SUMMARY_STARTED"},API_AVAILABILITY:{AVAILABLE:"available",UNAVAILABLE:"unavailable",LOADING:"loading"},SUMMARIZER_OPTIONS:{TYPE:"tldr",FORMAT:"markdown",LENGTH:"medium"},CHUNKING_OPTIONS:{CHUNK_SIZE:3e3,CHUNK_OVERLAP:200,MIN_CHUNK_SIZE:100,MAX_TOKENS_ESTIMATE:750},CONTEXT_MENU_ID:"summarize-text",ERROR_MESSAGES:{API_UNAVAILABLE:"The Summarizer API isn't usable",PROCESSING_FAILED:"Failed to process summarization",INVALID_GENERATION:"Invalid generation level",MISSING_TEXT_OR_LEVEL:"Missing text or level"}};export{r as A,i as a,o as b,n as g,s as l};
